#' Download the LCZ map from LCZ Generator
#'
#' Retrieves the LCZ map produced by the LCZ Generator web application.
#'
#' @param ID A code generated by LCZ Factsheet, e.g.
#'   `"3110e623fbe4e73b1cde55f0e9832c4f5640ac21"`.
#' @param band Feature to use: `"lcz"` or `"lczFilter"` (default).
#' @param isave_map Logical. Save the map as a GeoTIFF.
#' @param lang Language used for console messages and errors. See
#'   [lcz_langs()]. Defaults to `"en"`.
#'
#' @return A `SpatRaster` with LCZ classes (1-17).
#'
#' @export
#'
#' @references
#' Demuzere, M., Kittner, J., and Bechtel, B. (2021). LCZ Generator: a web
#' application to create Local Climate Zone maps. Frontiers in Environmental
#' Science 9:637455. \doi{10.3389/fenvs.2021.637455}
#'
#' @examples
#' \dontrun{
#' my_lcz_map <- lcz_get_map_generator(
#'   ID = "3110e623fbe4e73b1cde55f0e9832c4f5640ac21"
#' )
#' }
#'
#' @keywords LCZ, Local Climate Zone, urban climate, LCZ Generator

lcz_get_map_generator <- function(ID = "3110e623fbe4e73b1cde55f0e9832c4f5640ac21",
                                  band = "lczFilter", isave_map = FALSE,
                                  lang = "en") {
  if (is.null(ID) || !nzchar(ID)) {
    lcz_abort("err_id", lang = lang)
  }
  band <- match.arg(band, c("lcz", "lczFilter"))

  url <- paste0(
    "https://lcz-generator.rub.de/factsheets/", ID, "/", ID, ".tif"
  )
  download <- lcz_remote_raster(url, lang = lang)

  out <- download[[band]]
  names(out) <- "lcz"

  if (isTRUE(isave_map)) {
    dir <- lcz_output_dir()
    terra::writeRaster(out, file.path(dir, "lcz_map_generator.tif"),
                       overwrite = TRUE)
    lcz_msg("msg_files_saved", lang = lang, path = dir)
  }

  out
}
